export const script = { nextResponse: null, queue: [], shown: [] };
class Form { constructor() { this.buttons = []; this.controls = []; } title(t) { this.t = t; return this; } body(b) { this.b = b; return this; } button(l) { this.buttons.push(l); return this; } button1(l) { return this.button(l); } button2(l) { return this.button(l); }
  dropdown(l, o) { this.controls.push(["dropdown", l, o]); return this; } slider(l) { this.controls.push(["slider", l]); return this; } toggle(l, d) { this.controls.push(["toggle", l, d]); return this; } textField(l) { this.controls.push(["text", l]); return this; }
  show(player) { script.shown.push(this); let r = script.queue.length ? script.queue.shift() : script.nextResponse; if (!script.queue.length) script.nextResponse = null; return Promise.resolve(r ?? { canceled: true }); } }
export class ActionFormData extends Form {} export class ModalFormData extends Form {} export class MessageFormData extends Form {}
